const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n  refreshTokens     RefreshToken[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  paystackConnected Boolean  @default(false)\n  status          StoreStatus @default(PENDING)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)\n  loyaltyEnabled    Boolean     @default(false)\n  themeSettings     Json?  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  bundles              Bundle[]\n  groupBuys            GroupBuy[]\n  milestones           Milestone[]\n  whatsappBroadcasts   WhatsappBroadcast[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  isActive        Boolean       @default(true)\n  sourceUrl       String?\n  stockQuantity   Int?\n  metadata        Json?\n  currency        String?\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n  groupBuys       GroupBuy[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  country         String?\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  totalOrders     Int       @default(0)\n  city            String?\n  notes           String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  fulfillmentStatus String      @default(\"UNFULFILLED\")\n  carrier         String?\n  shippedAt       DateTime?\n  paymentStatus   String      @default(\"PENDING\")\n  tax               Float       @default(0)\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  discountType  String?   // alias for type\n  discountValue Float     @default(0)\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usageLimit    Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  storeId   String?\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  archived  Boolean      @default(false)\n  pinned    Boolean      @default(false)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  metadata       Json?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n\n\n\n\n\n\n\n\n\n\nmodel RefreshToken {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token       String    @unique\n  expiresAt   DateTime\n  revokedAt   DateTime?\n  ipAddress   String?\n  userAgent   String?\n  createdAt   DateTime  @default(now())\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel KaiMemory {\n  id         String   @id @default(uuid())\n  userId     String?\n  storeId    String?\n  key        String\n  value      String\n  category              String   @default(\"general\")\n  confidence            Float    @default(1.0)\n  sourceConversationId  String?\n  lastUsed   DateTime @default(now())\n  ttl        DateTime?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  @@unique([userId, key])\n  @@unique([storeId, key], name: \"storeId_key\")\n  @@map(\"kai_memories\")\n}\n\nmodel KaiGoal {\n  id           String   @id @default(uuid())\n  userId       String\n  storeId      String\n  title        String\n  description  String?\n  target       Float?\n  targetValue  Float?\n  current      Float    @default(0)\n  currentValue Float    @default(0)\n  unit         String   @default(\"NGN\")\n  status       String   @default(\"active\")\n  deadline     DateTime?\n  achieved     Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  @@map(\"kai_goals\")\n}\n\nmodel KaiMarketCache {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  data        Json\n  category    String   @default(\"general\")\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_market_cache\")\n}\n\nmodel KaiPulseAlert {\n  id        String   @id @default(uuid())\n  storeId         String\n  userId          String?\n  type            String\n  title           String\n  message         String\n  data            Json?\n  read            Boolean  @default(false)\n  priority        String   @default(\"normal\")\n  severity        String   @default(\"info\")\n  actionable      Boolean  @default(false)\n  suggestedPrompt String?\n  createdAt  DateTime @default(now())\n  @@index([storeId])\n  @@index([userId])\n  @@map(\"kai_pulse_alerts\")\n}\n\nmodel KaiMorningBrief {\n  id                String   @id @default(uuid())\n  userId            String\n  storeId           String\n  content           String\n  date              DateTime @default(now())\n  delivered         Boolean  @default(false)\n  topOpportunity    String?\n  revenueLastNight  Float    @default(0)\n  ordersLastNight   Int      @default(0)\n  urgentAction      String?\n  @@unique([storeId, date], name: \"storeId_date\")\n  @@map(\"kai_morning_briefs\")\n}\n\nmodel KaiBrandVoice {\n  id         String   @id @default(uuid())\n  storeId    String   @unique\n  tone       String   @default(\"friendly\")\n  style      String   @default(\"conversational\")\n  keywords   String[] @default([])\n  avoidWords  String[] @default([])\n  examples    String[] @default([])\n  usesEmojis     Boolean  @default(true)\n  language       String   @default(\"en\")\n  sentenceLength String   @default(\"medium\")\n  sampleContent  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_brand_voices\")\n}\n\nmodel KaiSkill {\n  id          String   @id @default(uuid())\n  userId      String\n  storeId     String?\n  name        String\n  description String?\n  prompt      String\n  useCount    Int      @default(0)\n  usageCount  Int      @default(0)\n  active      Boolean  @default(true)\n  isGlobal    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([userId])\n  @@map(\"kai_skills\")\n}\n\nmodel LoyaltyAccount {\n  id           String   @id @default(uuid())\n  storeId      String\n  customerId   String\n  points       Int      @default(0)\n  totalEarned  Int      @default(0)\n  totalSpent     Int      @default(0)\n  totalRedeemed  Int      @default(0)\n  tier           String   @default(\"bronze\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  transactions   LoyaltyTransaction[]\n  @@unique([storeId, customerId])\n  @@map(\"loyalty_accounts\")\n}\n\nmodel ReviewRequest {\n  id         String   @id @default(uuid())\n  orderId    String   @unique\n  storeId    String\n  customerId String?\n  email      String   @default(\"\")\n  sentAt     DateTime?\n  responded  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  @@map(\"review_requests\")\n}\n\nmodel ProfitProtectionRule {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  minMargin   Float    @default(20)\n  action      String   @default(\"alert\")\n  active      Boolean  @default(true)\n  isActive    Boolean  @default(true)\n  trigger     String   @default(\"margin_drop\")\n  threshold   Float    @default(20)\n  actionValue Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([storeId])\n  @@map(\"profit_protection_rules\")\n}\n\nmodel LoyaltyTransaction {\n  id          String   @id @default(uuid())\n  accountId   String\n  account     LoyaltyAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  type        String   // earn | redeem\n  points      Int\n  orderId     String?\n  description String?\n  createdAt   DateTime @default(now())\n  @@index([accountId])\n  @@map(\"loyalty_transactions\")\n}\n\nmodel WhatsappBroadcast {\n  id             String    @id @default(uuid())\n  storeId        String\n  message        String\n  recipients     Int       @default(0)\n  recipientCount Int       @default(0)\n  sent           Int       @default(0)\n  sentCount      Int       @default(0)\n  failed         Int       @default(0)\n  status         String    @default(\"pending\")\n  scheduledAt    DateTime?\n  sentAt         DateTime?\n  store          Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  @@index([storeId])\n  @@map(\"whatsapp_broadcasts\")\n}\n\nmodel KaiActionLog {\n  id             String   @id @default(uuid())\n  storeId        String\n  conversationId String?\n  actionType     String\n  payload        Json?\n  approved       Boolean  @default(false)\n  executed       Boolean  @default(false)\n  result         Json?\n  createdAt      DateTime @default(now())\n  @@index([storeId])\n  @@map(\"kai_action_logs\")\n}\n","backend/src/controllers/features.controller.ts":"// ============================================================\n// DropOS — Priority 1-3 Features Controller\n// Path: backend/src/controllers/features.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { PrismaClient } from \"@prisma/client\";\nimport {\n  calculateHealthScore, gradeProducts, getAtRiskCustomers,\n  getStoreAchievements, getRevenueReplay, getWeeklyWinners,\n  createPriceTest,\n} from \"../services/features.service\";\n\nconst prisma = new PrismaClient();\n\n// ── GET /api/features/health/:storeId ─────────────────────────\nexport async function healthScore(req: Request, res: Response) {\n  try {\n    const data = await calculateHealthScore(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/product-grades/:storeId ─────────────────\nexport async function productGrades(req: Request, res: Response) {\n  try {\n    const data = await gradeProducts(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/at-risk/:storeId ────────────────────────\nexport async function atRiskCustomers(req: Request, res: Response) {\n  try {\n    const data = await getAtRiskCustomers(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/achievements/:storeId ───────────────────\nexport async function achievements(req: Request, res: Response) {\n  try {\n    const data = await getStoreAchievements(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/replay/:storeId ─────────────────────────\nexport async function revenueReplay(req: Request, res: Response) {\n  try {\n    const data = await getRevenueReplay(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/weekly-winners/:storeId ─────────────────\nexport async function weeklyWinners(req: Request, res: Response) {\n  try {\n    const data = await getWeeklyWinners(req.params.storeId);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/features/price-test ────────────────────────────\nexport async function priceTest(req: Request, res: Response) {\n  try {\n    const { storeId, productId, priceA, priceB } = req.body;\n    if (!storeId || !productId || !priceA || !priceB)\n      return res.status(400).json({ success: false, message: \"storeId, productId, priceA, priceB required\" });\n    const data = await createPriceTest(storeId, productId, Number(priceA), Number(priceB));\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/live-sales/:storeId ────────────────────\n// Returns the last 10 orders for the live ticker\nexport async function liveSales(req: Request, res: Response) {\n  try {\n    const { storeId } = req.params;\n    const orders = await prisma.order.findMany({\n      where: { storeId, status: { in: [\"COMPLETED\", \"SHIPPED\", \"DELIVERED\"] } },\n      orderBy: { createdAt: \"desc\" },\n      take: 10,\n      include: {\n        customer: { select: { name: true, city: true } },\n        items: { take: 1, include: { product: { select: { name: true } } } },\n      } as any,\n    });\n\n    const feed = (orders as any[]).map((o: any) => ({\n      id: o.id,\n      customerName: o.customer?.name?.split(\" \")[0] || \"Someone\",\n      city: o.customer?.city || \"Nigeria\",\n      productName: o.items[0]?.product?.name || \"a product\",\n      amount: Number(o.total),\n      createdAt: o.createdAt,\n      minutesAgo: Math.round((Date.now() - new Date(o.createdAt).getTime()) / 60000),\n    }));\n\n    res.json({ success: true, data: feed });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/features/send-comeback ─────────────────────────\n// Send win-back WhatsApp message to at-risk customer\nexport async function sendComeback(req: Request, res: Response) {\n  try {\n    const { customerId, message, storeId } = req.body;\n    // Store the intent — actual WhatsApp sending handled by WhatsApp service\n    await prisma.storeCustomer.update({\n      where: { id: customerId },\n      data: { notes: `Win-back sent ${new Date().toLocaleDateString()}` } as any,\n    });\n    res.json({ success: true, message: \"Win-back message queued\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/features/store-setup-status ─────────────────────\n// Check what's needed for 5-min store setup\nexport async function setupStatus(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    const [store, products, shipping] = await Promise.all([\n      prisma.store.findUnique({\n        where: { id: storeId },\n        select: { name: true, logo: true, description: true, country: true, currency: true },\n      }),\n      prisma.product.count({ where: { storeId } }),\n      prisma.shippingZone?.count({ where: { storeId } }).catch(() => 0),\n    ]);\n\n    const steps = [\n      { id: \"store_info\",  label: \"Store info\",        done: !!(store?.name && store?.description) },\n      { id: \"logo\",        label: \"Store logo\",        done: !!store?.logo },\n      { id: \"products\",    label: \"Add products\",      done: products >= 3 },\n      { id: \"shipping\",    label: \"Set up shipping\",   done: (shipping || 0) >= 1 },\n      { id: \"payment\",     label: \"Connect payment\",   done: true }, // assume Paystack connected on signup\n    ];\n\n    const percent = Math.round((steps.filter(s => s.done).length / steps.length) * 100);\n    res.json({ success: true, data: { steps, percent, isComplete: percent === 100 } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n","backend/src/controllers/kai.controller.ts":"// ============================================================\n// KAI — Complete Controller (10/10)\n// Path: backend/src/controllers/kai.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { PrismaClient } from \"@prisma/client\";\nimport {\n  getStoreContext, buildCompleteSystemPrompt, callClaude,\n  detectIntent, needsWebSearch, generateTitle,\n  buildGreeting, buildQuickActions,\n} from \"../services/kai.service\";\nimport {\n  extractMemoriesFromConversation, getMemories, saveMemory,\n  deleteMemory, getActiveGoals, analyzeBrandVoice,\n} from \"../services/kai.memory.service\";\nimport {\n  getUnreadAlerts, markAlertRead, analyzeStore,\n} from \"../services/kai.pulse.service\";\nimport { getKaiSkills } from \"../services/kai.market.service\";\n\nconst prisma = new PrismaClient();\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// ── GET /api/kai/greeting ─────────────────────────────────────\nexport async function getGreeting(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n\n    const [ctx, alerts] = await Promise.all([\n      getStoreContext(storeId),\n      getUnreadAlerts(storeId),\n    ]);\n\n    const user      = (req as any).user;\n    const firstName = (user?.name || \"there\").split(\" \")[0];\n    const hour      = new Date().getHours();\n\n    const { greeting, contextLine } = buildGreeting(firstName, ctx, hour);\n    const quickActions = buildQuickActions(ctx);\n\n    res.json({\n      success: true,\n      data: { greeting, name: firstName, contextLine, quickActions, storeContext: ctx, unreadAlerts: alerts.length },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversations ────────────────────────────────\nexport async function getConversations(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n\n    const conversations = await prisma.kaiConversation.findMany({\n      where: { storeId, archived: false },\n      orderBy: [{ pinned: \"desc\" }, { updatedAt: \"desc\" }],\n      select: {\n        id: true, title: true, pinned: true, createdAt: true, updatedAt: true,\n        messages: { orderBy: { createdAt: \"desc\" }, take: 1, select: { content: true, role: true } },\n      },\n    });\n    res.json({ success: true, data: conversations });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversation/:id ─────────────────────────────\nexport async function getConversation(req: Request, res: Response) {\n  try {\n    const conv = await prisma.kaiConversation.findUnique({\n      where: { id: req.params.id },\n      include: { messages: { orderBy: { createdAt: \"asc\" } } },\n    });\n    if (!conv) return res.status(404).json({ success: false, message: \"Not found\" });\n    res.json({ success: true, data: conv });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/smart-chat (STREAMING + MEMORY) ────────────\nexport async function smartChat(req: Request, res: Response) {\n  const { message, conversationId, storeId, imageBase64, imageMediaType } = req.body;\n  if (!message || !storeId)\n    return res.status(400).json({ success: false, message: \"message and storeId required\" });\n\n  try {\n    // Get or create conversation\n    let conv: any = conversationId\n      ? await prisma.kaiConversation.findUnique({\n          where: { id: conversationId },\n          include: { messages: { orderBy: { createdAt: \"asc\" }, take: 20 } },\n        })\n      : null;\n\n    if (!conv) {\n      conv = await (prisma.kaiConversation as any).create({\n        data: { storeId, title: generateTitle(message) },\n        include: { messages: true },\n      });\n    }\n\n    // Save user message\n    await (prisma.kaiMessage as any).create({\n      data: { conversationId: conv.id, role: \"user\", content: message },\n    });\n\n    // Get everything in parallel\n    const [ctx, intent] = await Promise.all([\n      getStoreContext(storeId),\n      Promise.resolve(detectIntent(message)),\n    ]);\n    const useSearch = needsWebSearch(message, intent);\n\n    // Build conversation history\n    const history = (conv.messages || [])\n      .slice(-8)\n      .map((m: any) => `${m.role === \"user\" ? \"Owner\" : \"KAI\"}: ${m.content.slice(0, 200)}`)\n      .join(\"\\n\");\n\n    // Build complete system prompt (includes memory, goals, brand voice, market data)\n    const systemPrompt = await buildCompleteSystemPrompt(ctx, storeId, history);\n\n    // Build messages array\n    const claudeMsgs: any[] = [];\n    for (const m of (conv.messages || []).slice(-6)) {\n      claudeMsgs.push({ role: m.role, content: m.content });\n    }\n    // Current message (with optional image)\n    const currentContent: any[] = [];\n    if (imageBase64 && imageMediaType) {\n      currentContent.push({ type: \"image\", source: { type: \"base64\", media_type: imageMediaType, data: imageBase64 } });\n    }\n    currentContent.push({ type: \"text\", text: message });\n    claudeMsgs.push({ role: \"user\", content: currentContent.length === 1 ? message : currentContent });\n\n    // Stream response\n    res.setHeader(\"Content-Type\", \"text/event-stream\");\n    res.setHeader(\"Cache-Control\", \"no-cache\");\n    res.setHeader(\"Connection\", \"keep-alive\");\n\n    let fullResponse = \"\";\n\n    await callClaude({\n      systemPrompt,\n      messages: claudeMsgs,\n      useSearch,\n      maxTokens: 1024,\n      onToken: (token) => {\n        fullResponse += token;\n        res.write(`data: ${JSON.stringify({ token, conversationId: conv.id })}\\n\\n`);\n      },\n    });\n\n    // Save KAI response\n    await (prisma.kaiMessage as any).create({\n      data: {\n        conversationId: conv.id,\n        role: \"assistant\",\n        content: fullResponse,\n        metadata: { intent, searched: useSearch },\n      },\n    });\n\n    await prisma.kaiConversation.update({\n      where: { id: conv.id },\n      data: { updatedAt: new Date() },\n    });\n\n    // Extract memories in background (don't await — don't slow down response)\n    if (apiKey()) {\n      extractMemoriesFromConversation(storeId, message, fullResponse, conv.id, apiKey())\n        .catch(err => console.error(\"Memory extraction error:\", err));\n    }\n\n    res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id })}\\n\\n`);\n    res.end();\n\n  } catch (err: any) {\n    console.error(\"KAI smart-chat error:\", err);\n    if (!res.headersSent) {\n      res.status(500).json({ success: false, message: \"KAI is temporarily unavailable\" });\n    } else {\n      res.write(`data: ${JSON.stringify({ error: true })}\\n\\n`);\n      res.end();\n    }\n  }\n}\n\n// ── POST /api/kai/action ──────────────────────────────────────\nexport async function executeAction(req: Request, res: Response) {\n  const { conversationId, storeId, actions } = req.body;\n  if (!actions?.length) return res.status(400).json({ success: false, message: \"actions required\" });\n\n  const results = [];\n  for (const action of actions) {\n    if (!action.approved) continue;\n    try {\n      let result: any = null;\n      switch (action.type) {\n        case \"update_order_status\":\n          result = await prisma.order.update({ where: { id: action.payload.orderId }, data: { status: action.payload.status } });\n          break;\n        case \"create_coupon\":\n          result = await (prisma.coupon as any).create({\n            data: { storeId, code: action.payload.code, discountType: action.payload.discountType || \"PERCENTAGE\",\n              discountValue: action.payload.discountValue, isActive: true,\n              expiresAt: action.payload.expiresAt ? new Date(action.payload.expiresAt) : null },\n          });\n          break;\n        case \"update_price\":\n          result = await prisma.product.update({ where: { id: action.payload.productId }, data: { price: action.payload.price } });\n          break;\n        case \"update_goal\":\n          result = await prisma.kaiGoal.upsert({\n            where: { id: action.payload.goalId || \"new\" },\n            create: { storeId, userId: (req as AuthRequest).user?.userId || (req as AuthRequest).user?.id || 'system', title: action.payload.title, targetValue: action.payload.targetValue,\n              currentValue: 0, unit: action.payload.unit, deadline: new Date(action.payload.deadline) },\n            update: { currentValue: action.payload.currentValue },\n          });\n          break;\n        default:\n          result = { note: `Action ${action.type} logged for manual execution` };\n      }\n      await (prisma.kaiActionLog as any).create({\n        data: { storeId, conversationId: conversationId || \"\", actionType: action.type,\n          payload: action.payload, approved: true, executed: true, result },\n      });\n      results.push({ actionId: action.id, success: true, result });\n    } catch (err: any) {\n      results.push({ actionId: action.id, success: false, error: err.message });\n    }\n  }\n  res.json({ success: true, data: results });\n}\n\n// ── PATCH /api/kai/conversation/:id ──────────────────────────\nexport async function updateConversation(req: Request, res: Response) {\n  try {\n    const { title, pinned, archived } = req.body;\n    const updated = await prisma.kaiConversation.update({\n      where: { id: req.params.id },\n      data: {\n        ...(title    !== undefined && { title }),\n        ...(pinned   !== undefined && { pinned }),\n        ...(archived !== undefined && { archived }),\n      },\n    });\n    res.json({ success: true, data: updated });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversation/:id ─────────────────────────\nexport async function deleteConversation(req: Request, res: Response) {\n  try {\n    await prisma.kaiConversation.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversations/all ────────────────────────\nexport async function deleteAllConversations(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    await prisma.kaiConversation.deleteMany({ where: { storeId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/memories ─────────────────────────────────────\nexport async function getKaiMemories(req: Request, res: Response) {\n  try {\n    const { storeId, category } = req.query as { storeId: string; category?: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const memories = await getMemories(storeId, category);\n    res.json({ success: true, data: memories });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/memory/:key ───────────────────────────────\nexport async function deleteKaiMemory(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    await deleteMemory(storeId, req.params.key);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/pulse ────────────────────────────────────────\nexport async function getPulseAlerts(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const alerts = await getUnreadAlerts(storeId);\n    res.json({ success: true, data: alerts });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── PATCH /api/kai/pulse/:id/read ────────────────────────────\nexport async function readPulseAlert(req: Request, res: Response) {\n  try {\n    await markAlertRead(req.params.id);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/skills ───────────────────────────────────────\nexport async function getSkills(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const skills = await getKaiSkills(storeId);\n    res.json({ success: true, data: skills });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills ──────────────────────────────────────\nexport async function createSkill(req: Request, res: Response) {\n  try {\n    const { storeId, name, prompt, description, icon, variables } = req.body;\n    if (!storeId || !name || !prompt) return res.status(400).json({ success: false, message: \"storeId, name, prompt required\" });\n    const skill = await (prisma.kaiSkill as any).create({\n      data: { storeId, name, prompt, description, icon, variables: variables || [] },\n    });\n    res.json({ success: true, data: skill });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/skills/:id ────────────────────────────────\nexport async function deleteSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills/:id/use ─────────────────────────────\nexport async function useSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.update({\n      where: { id: req.params.id },\n      data: { usageCount: { increment: 1 } },\n    });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/analyze-voice ───────────────────────────────\nexport async function analyzeVoice(req: Request, res: Response) {\n  try {\n    const { storeId, content } = req.body;\n    if (!storeId || !content) return res.status(400).json({ success: false, message: \"storeId and content required\" });\n    await analyzeBrandVoice(storeId, content, apiKey());\n    res.json({ success: true, message: \"Brand voice analyzed and saved\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/goals ────────────────────────────────────────\nexport async function getGoals(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const goals = await prisma.kaiGoal.findMany({\n      where: { storeId },\n      \n      orderBy: { deadline: \"asc\" },\n    });\n    res.json({ success: true, data: goals });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/goals ───────────────────────────────────────\nexport async function createGoal(req: Request, res: Response) {\n  try {\n    const { storeId, title, targetValue, unit, deadline, description } = req.body;\n    if (!storeId || !title || !targetValue || !deadline)\n      return res.status(400).json({ success: false, message: \"storeId, title, targetValue, deadline required\" });\n\n    const goal = await (prisma.kaiGoal as any).create({\n      data: { storeId, title, description, targetValue, unit: unit || \"NGN\", deadline: new Date(deadline) },\n      \n    });\n\n    // Save to memory\n    await saveMemory(storeId, \"goal\", `goal_${goal.id}`,\n      `Owner wants to ${title} by ${new Date(deadline).toLocaleDateString()}`, 1.0);\n\n    res.json({ success: true, data: goal });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n","backend/src/controllers/kai.intelligence.controller.ts":"// ============================================================\n// KAI Intelligence Controller + Routes\n// Path: backend/src/controllers/kai.intelligence.controller.ts\n// Add to app.ts: app.use(\"/api/intel\", intelRoutes);\n// ============================================================\nimport { Request, Response } from \"express\";\nimport {\n  runAdSpy, generateTikTokScript, getDailyTop10,\n  getProfitRules, createProfitRule, evaluateProfitRules,\n  bulkScrapeSupplierStore, checkFulfillmentStatus, markOrderFulfilling,\n  syncPricesAndStock, spyCompetitorStore, findSupplierAlternatives,\n} from \"../services/kai.intelligence.service\";\nimport prisma from \"../lib/prisma\";\n\nconst wrap = (fn: Function) => async (req: Request, res: Response) => {\n  try {\n    const data = await fn(req);\n    res.json({ success: true, data });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message || \"Failed\" });\n  }\n};\n\n// ── Ad Spy ────────────────────────────────────────────────────\nexport const adSpy = wrap(async (req: Request) => {\n  const { query, platform = \"all\", storeId } = req.body;\n  if (!query) throw new Error(\"query required\");\n  const store  = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return runAdSpy({ query, platform, country: store?.country || \"NG\", storeId });\n});\n\n// ── TikTok Script ─────────────────────────────────────────────\nexport const tikTokScript = wrap(async (req: Request) => {\n  const { productName, productDesc, price, storeId, duration = 30, angle } = req.body;\n  if (!productName || !price) throw new Error(\"productName and price required\");\n  const store  = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return generateTikTokScript({ productName, productDesc, price: Number(price), country: store?.country || \"NG\", duration, angle });\n});\n\n// ── Daily Top 10 ──────────────────────────────────────────────\nexport const dailyTop10 = wrap(async (req: Request) => {\n  const { storeId } = req.query as any;\n  return getDailyTop10(storeId);\n});\n\n// ── Profit Rules ──────────────────────────────────────────────\nexport const listProfitRules = wrap(async (req: Request) => {\n  return getProfitRules(req.params.storeId);\n});\nexport const addProfitRule = wrap(async (req: Request) => {\n  const { storeId, ...rule } = req.body;\n  return createProfitRule(storeId, rule);\n});\nexport const deleteProfitRule = wrap(async (req: Request) => {\n  await prisma.profitProtectionRule.update({ where: { id: req.params.id }, data: { isActive: false } });\n  return { deleted: true };\n});\nexport const runProfitCheck = wrap(async (req: Request) => {\n  return evaluateProfitRules(req.params.storeId);\n});\n\n// ── Bulk Import ───────────────────────────────────────────────\nexport const bulkImport = wrap(async (req: Request) => {\n  const { storeUrl, storeId, limit } = req.body;\n  if (!storeUrl) throw new Error(\"storeUrl required\");\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return bulkScrapeSupplierStore({ storeUrl, country: store?.country || \"NG\", limit: Number(limit) || 20 });\n});\n\nexport const confirmBulkImport = wrap(async (req: Request) => {\n  const { storeId, products, pricingRule } = req.body;\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  const { getLocale } = require(\"../utils/kai.locale\");\n  const locale = getLocale(store?.country || \"NG\");\n\n  const created = await Promise.all(\n    (products as any[]).map((p: any) => {\n      const sellingPrice = pricingRule === \"2x\" ? p.localCost * 2\n        : pricingRule === \"2.5x\" ? p.localCost * 2.5\n        : pricingRule === \"3x\"   ? p.localCost * 3\n        : p.suggestedLocalPrice || p.localCost * 2.5;\n\n      return (prisma.product as any).create({\n        data: {\n          storeId, name: p.name,\n          price: Math.round(sellingPrice),\n          costPrice: p.localCost,\n          stockQuantity: 50,\n          category: p.category || \"General\",\n          images: p.image ? [p.image] : [],\n          sourceUrl: p.supplierUrl,\n          isActive: true,\n        },\n      }).catch(() => null);\n    })\n  );\n\n  return { imported: created.filter(Boolean).length, total: products.length };\n});\n\n// ── Fulfillment ───────────────────────────────────────────────\nexport const fulfillmentQueue = wrap(async (req: Request) => {\n  const { storeId } = req.query as any;\n  return checkFulfillmentStatus(storeId);\n});\n\nexport const fulfillOrder = wrap(async (req: Request) => {\n  const { orderId, trackingNumber, carrier } = req.body;\n  return markOrderFulfilling(orderId, trackingNumber, carrier);\n});\n\n// ── Price Sync ────────────────────────────────────────────────\nexport const priceSync = wrap(async (req: Request) => {\n  const { storeId } = req.params;\n  return syncPricesAndStock(storeId);\n});\n\n// ── Competitor Spy ────────────────────────────────────────────\nexport const competitorSpy = wrap(async (req: Request) => {\n  const { storeUrl, storeId } = req.body;\n  if (!storeUrl) throw new Error(\"storeUrl required\");\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return spyCompetitorStore({ storeUrl, country: store?.country || \"NG\" });\n});\n\n// ── Supplier Finder ───────────────────────────────────────────\nexport const supplierFinder = wrap(async (req: Request) => {\n  const { productName, currentUrl, storeId, maxPriceUSD } = req.body;\n  if (!productName) throw new Error(\"productName required\");\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  return findSupplierAlternatives({ productName, currentUrl, country: store?.country || \"NG\", maxPriceUSD });\n});\n\n// ── ROUTES ────────────────────────────────────────────────────\nimport { Router }    from \"express\";\nimport rateLimit     from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\n\nconst router   = Router();\nconst aiLimit  = rateLimit({ windowMs: 60000, max: 10, message: { success: false, message: \"Too many AI requests — wait a moment\" } });\n\nrouter.use(authenticate);\n\n// Ad Spy\nrouter.post(\"/ad-spy\",                aiLimit, adSpy);\n\n// TikTok Scripts\nrouter.post(\"/tiktok-script\",         aiLimit, tikTokScript);\n\n// Daily Top 10\nrouter.get (\"/daily-top10\",           aiLimit, dailyTop10);\n\n// Profit Rules\nrouter.get (\"/profit-rules/:storeId\", listProfitRules);\nrouter.post(\"/profit-rules\",          addProfitRule);\nrouter.delete(\"/profit-rules/:id\",    deleteProfitRule);\nrouter.post(\"/profit-rules/:storeId/run\", aiLimit, runProfitCheck);\n\n// Bulk Import\nrouter.post(\"/bulk-import\",           aiLimit, bulkImport);\nrouter.post(\"/bulk-import/confirm\",   confirmBulkImport);\n\n// Fulfillment\nrouter.get (\"/fulfillment\",           fulfillmentQueue);\nrouter.post(\"/fulfillment/fulfill\",   fulfillOrder);\n\n// Price Sync\nrouter.post(\"/price-sync/:storeId\",   aiLimit, priceSync);\n\n// Competitor Spy\nrouter.post(\"/competitor-spy\",        aiLimit, competitorSpy);\n\n// Supplier Finder\nrouter.post(\"/suppliers\",             aiLimit, supplierFinder);\n\nexport default router;\n","backend/src/controllers/payment.controller.ts":"// src/controllers/payment.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { calculateFee, detectGateway } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport {\n  createStripePaymentIntent, constructStripeEvent,\n  initializePaystack, verifyPaystack, verifyPaystackWebhook,\n  initializeFlutterwave, verifyFlutterwave, verifyFlutterwaveWebhook,\n} from \"../services/payment.service\";\nimport { emailService } from \"../services/email.service\";\nimport { logger } from \"../utils/logger\";\n\n// ── Initialize Payment ────────────────────────────────────────────────────────\nexport const initializePayment = async (req: Request, res: Response) => {\n  const schema = z.object({\n    orderId:   z.string().uuid(),\n    gateway:   z.enum([\"STRIPE\",\"PAYSTACK\",\"FLUTTERWAVE\"]).optional(),\n    country:   z.string().optional(),\n  });\n  const { orderId, gateway: manualGateway, country } = schema.parse(req.body);\n\n  const order = await prisma.order.findUnique({\n    where: { id: orderId },\n    include: { store: true },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  if ((order as any).payment) throw new AppError(\"Payment already initiated for this order\", 400);\n\n  // Auto-detect gateway\n  const gateway = manualGateway || detectGateway(country);\n\n  const feePercent = await getPlatformFee();\n  const { platformFee, storeEarnings } = calculateFee(order.total, feePercent);\n\n  const frontendUrl = process.env.FRONTEND_URL || \"http://localhost:3000\";\n  const storeSlug   = order.store?.slug || \"\";\n  // Correct callback URL: points to the actual payment/callback page with real orderId\n  const callbackUrl = `${frontendUrl}/store/${storeSlug}/payment/callback?orderId=${orderId}`;\n\n  let initData: any = {};\n\n  if (gateway === \"STRIPE\") {\n    initData = await createStripePaymentIntent({\n      amount:        order.total,\n      currency:      order.currency,\n      orderId:       order.id,\n      storeId:       order.storeId,\n      customerEmail: order.customerEmail,\n    });\n  } else if (gateway === \"PAYSTACK\") {\n    initData = await initializePaystack({\n      amount:      order.total,\n      currency:    order.currency === \"NGN\" ? \"NGN\" : \"NGN\",\n      email:       order.customerEmail,\n      orderId:     order.id,\n      storeId:     order.storeId,\n      callbackUrl,\n    });\n  } else if (gateway === \"FLUTTERWAVE\") {\n    initData = await initializeFlutterwave({\n      amount:      order.total,\n      currency:    order.currency,\n      email:       order.customerEmail,\n      name:        order.customerName,\n      phone:       order.customerPhone || undefined,\n      orderId:     order.id,\n      storeId:     order.storeId,\n      redirectUrl: callbackUrl,\n    });\n  }\n\n  // Create pending payment record\n  await (prisma.payment as any).create({\n    data: {\n      orderId,\n      storeId:           order.storeId,\n      gateway:           gateway as any,\n      amount:            order.total,\n      currency:          order.currency,\n      platformFee,\n      platformFeePercent: feePercent,\n      storeEarnings,\n      status:            \"PENDING\",\n      metadata:          initData,\n    },\n  });\n\n  return res.json({\n    success: true,\n    data: { gateway, ...initData, amount: order.total, currency: order.currency },\n  });\n};\n\n// ── Stripe Webhook ────────────────────────────────────────────────────────────\nexport const stripeWebhook = async (req: Request, res: Response) => {\n  const sig = req.headers[\"stripe-signature\"] as string;\n  const event = constructStripeEvent(req.body as Buffer, sig);\n\n  if (event.type === \"payment_intent.succeeded\") {\n    const intent = event.data.object as any;\n    const orderId = intent.metadata?.orderId;\n    if (orderId) await completePayment(orderId, intent.id, \"STRIPE\");\n  }\n\n  if (event.type === \"payment_intent.payment_failed\") {\n    const intent = event.data.object as any;\n    const orderId = intent.metadata?.orderId;\n    if (orderId) await failPayment(orderId, \"STRIPE\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Paystack Webhook ──────────────────────────────────────────────────────────\nexport const paystackWebhook = async (req: Request, res: Response) => {\n  const sig     = req.headers[\"x-paystack-signature\"] as string;\n  const payload = (req.body as Buffer).toString();\n\n  if (!verifyPaystackWebhook(payload, sig)) {\n    throw new AppError(\"Invalid webhook signature\", 400);\n  }\n\n  let event: any;\n  try { event = JSON.parse(payload); } catch { return res.json({ received: true }); }\n\n  if (event.event === \"charge.success\") {\n    const orderId = event.data?.metadata?.orderId;\n    if (orderId) await completePayment(orderId, event.data.reference, \"PAYSTACK\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Flutterwave Webhook ───────────────────────────────────────────────────────\nexport const flutterwaveWebhook = async (req: Request, res: Response) => {\n  const sig     = req.headers[\"verif-hash\"] as string;\n  const payload = (req.body as Buffer).toString();\n\n  if (sig !== process.env.FLUTTERWAVE_SECRET_KEY) {\n    throw new AppError(\"Invalid webhook signature\", 400);\n  }\n\n  let event: any;\n  try { event = JSON.parse(payload); } catch { return res.json({ received: true }); }\n\n  if (event.status === \"successful\") {\n    const orderId = event.meta?.orderId;\n    if (orderId) await completePayment(orderId, String(event.id), \"FLUTTERWAVE\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Verify Payment (after redirect) ──────────────────────────────────────────\nexport const verifyPayment = async (req: Request, res: Response) => {\n  const { orderId, reference, transaction_id } = req.query;\n  if (!orderId) throw new AppError(\"orderId required\", 400);\n\n  const payment = await prisma.payment.findUnique({ where: { orderId: orderId as string } });\n  if (!payment) throw new AppError(\"Payment not found\", 404);\n\n  if (payment.status === \"SUCCESS\") {\n    return res.json({ success: true, data: { status: \"SUCCESS\", payment } });\n  }\n\n  // Verify with gateway\n  if (payment.gateway === \"PAYSTACK\" && reference) {\n    const result = await verifyPaystack(reference as string);\n    if (result.status === \"success\") {\n      await completePayment(orderId as string, result.reference, \"PAYSTACK\");\n    }\n  }\n\n  if (payment.gateway === \"FLUTTERWAVE\" && transaction_id) {\n    const result = await verifyFlutterwave(transaction_id as string);\n    if (result.status === \"successful\") {\n      await completePayment(orderId as string, String(result.id), \"FLUTTERWAVE\");\n    }\n  }\n\n  const updated = await prisma.payment.findUnique({ where: { orderId: orderId as string } });\n\n  // Return order data alongside payment so the callback page can render the success screen\n  const orderData = await prisma.order.findUnique({\n    where:   { id: orderId as string },\n    include: { items: true, store: { select: { name: true, slug: true, primaryColor: true } } },\n  });\n\n  return res.json({ success: true, data: { ...updated, order: orderData } });\n};\n\n// ── Admin: Get All Payments ───────────────────────────────────────────────────\nexport const getAllPayments = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, gateway } = req.query;\n  const take = Math.min(Number(limit), 100);\n  const skip = (Math.max(Number(page), 1) - 1) * take;\n\n  const where: any = {};\n  if (status)  where.status  = status;\n  if (gateway) where.gateway = gateway;\n\n  const [payments, total] = await Promise.all([\n    await prisma.payment.findMany({\n      where, take, skip,\n      include: {\n        order: { select: { orderNumber: true, customerName: true, customerEmail: true } },\n        store: { select: { name: true, owner: { select: { name: true, email: true } } } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.payment.count({ where }),\n  ]);\n\n  const totals = await prisma.payment.aggregate({\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: payments,\n    totals: totals._sum,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Helpers ──────────────────────────────────────────────────────────────────\nasync function getPlatformFee(): Promise<number> {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return settings?.platformFeePercent || Number(process.env.PLATFORM_FEE_PERCENT || 10);\n}\n\nasync function completePayment(orderId: string, reference: string, gateway: string) {\n  try {\n    await prisma.$transaction([\n      prisma.payment.update({\n        where: { orderId },\n        data:  { status: \"SUCCESS\", gatewayReference: reference, paidAt: new Date() },\n      }),\n      prisma.order.update({\n        where: { id: orderId },\n        data:  { status: \"PROCESSING\" },\n      }),\n    ]);\n\n    const order = await prisma.order.findUnique({\n      where: { id: orderId },\n      include: { store: true, items: true },\n    });\n    if (order) {\n      // ── Customer confirmation email (with real line items) ─────────────────\n      await emailService.sendOrderConfirmation({\n        email:       order.customerEmail,\n        name:        order.customerName,\n        orderNumber: order.orderNumber,\n        total:       order.total,\n        currency:    order.currency,\n        storeName:   order.store?.name || \"Store\",\n        storeEmail:  order.store?.supportEmail || undefined,\n        items:       (order.items as any[]).map(i => ({\n          name:     i.name,\n          quantity: i.quantity,\n          price:    i.price,\n        })),\n      });\n\n      // ── Store owner new-order alert ────────────────────────────────────────\n      const owner = await prisma.user.findUnique({\n        where:  { id: order.store!.ownerId },\n        select: { email: true, name: true, phone: true },\n      });\n      if (owner) {\n        emailService.sendNewOrderAlert({\n          ownerEmail:   owner.email,\n          ownerName:    owner.name,\n          orderNumber:  order.orderNumber,\n          customerName: order.customerName,\n          total:        order.total,\n          currency:     order.currency,\n          storeName:    order.store!.name,\n          itemCount:    (order.items as any[]).length,\n        }).catch(() => {/* non-fatal */});\n      }\n\n      // ── Update customer spend stats ────────────────────────────────────────\n      if (order.customerId) {\n        await prisma.storeCustomer.update({\n          where: { id: order.customerId },\n          data: {\n            totalSpent: { increment: order.total },\n            orderCount: { increment: 1 },\n          },\n        });\n      }\n    }\n  } catch (err) {\n    logger.error(\"completePayment error:\", err);\n  }\n}\n\nasync function failPayment(orderId: string, gateway: string) {\n  try {\n    await prisma.payment.update({\n      where: { orderId },\n      data:  { status: \"FAILED\" },\n    });\n    logger.warn(`Payment failed for order ${orderId} via ${gateway}`);\n\n    // Notify customer\n    const order = await prisma.order.findUnique({\n      where:   { id: orderId },\n      include: { store: true },\n    });\n    if (order) {\n      const { emailService } = await import(\"../services/email.service\");\n      emailService.sendPaymentFailed(\n        order.customerEmail,\n        order.customerName,\n        order.orderNumber,\n        `$${order.total.toFixed(2)}`,\n        order.store?.name || \"Store\"\n      );\n    }\n  } catch (err) {\n    logger.error(\"failPayment error:\", err);\n  }\n}\n","backend/src/routes/supplier.routes.ts":"// src/routes/supplier.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { authenticate, AuthRequest } from \"../middleware/auth\";\nimport { AppError } from \"../utils/AppError\";\nimport { requireStoreOwner } from \"../controllers/store.controller\";\nimport { supplierService, FulfillmentPayload } from \"../services/supplier.service\";\n\nconst router = Router();\n\n// ── All routes require auth ───────────────────────────────────────────────────\nrouter.use(authenticate);\n\n// ── GET /api/suppliers/:storeId — list all suppliers ─────────────────────────\nrouter.get(\"/:storeId\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const suppliers = await prisma.supplier.findMany({\n    where:   { storeId },\n    include: {\n      _count: { select: { products: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  return res.json({ success: true, data: suppliers });\n});\n\n// ── POST /api/suppliers/:storeId — create supplier ────────────────────────────\nrouter.post(\"/:storeId\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const data = z.object({\n    name:         z.string().min(1).max(200),\n    type:         z.enum([\"MANUAL\",\"ALIEXPRESS\",\"CSV\",\"WEBHOOK\"]).default(\"MANUAL\"),\n    websiteUrl:   z.string().url().optional().or(z.literal(\"\")),\n    apiKey:       z.string().optional(),\n    apiSecret:    z.string().optional(),\n    contactEmail: z.string().email().optional().or(z.literal(\"\")),\n    contactName:  z.string().optional(),\n    notes:        z.string().optional(),\n    autoFulfill:  z.boolean().default(false),\n    fulfillEmail: z.string().email().optional().or(z.literal(\"\")),\n    webhookUrl:   z.string().url().optional().or(z.literal(\"\")),\n  }).parse(req.body);\n\n  const supplier = await (prisma.supplier as any).create({\n    data: { ...data, storeId },\n  });\n\n  return res.status(201).json({ success: true, data: supplier });\n});\n\n// ── PUT /api/suppliers/:storeId/:supplierId — update supplier ─────────────────\nrouter.put(\"/:storeId/:supplierId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, supplierId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const supplier = await prisma.supplier.findFirst({ where: { id: supplierId, storeId } });\n  if (!supplier) throw new AppError(\"Supplier not found\", 404);\n\n  const data = z.object({\n    name:         z.string().min(1).max(200).optional(),\n    type:         z.enum([\"MANUAL\",\"ALIEXPRESS\",\"CSV\",\"WEBHOOK\"]).optional(),\n    websiteUrl:   z.string().optional(),\n    apiKey:       z.string().optional(),\n    apiSecret:    z.string().optional(),\n    contactEmail: z.string().optional(),\n    contactName:  z.string().optional(),\n    notes:        z.string().optional(),\n    isActive:     z.boolean().optional(),\n    autoFulfill:  z.boolean().optional(),\n    fulfillEmail: z.string().optional(),\n    webhookUrl:   z.string().optional(),\n  }).parse(req.body);\n\n  const updated = await prisma.supplier.update({\n    where: { id: supplierId },\n    data,\n  });\n\n  return res.json({ success: true, data: updated });\n});\n\n// ── DELETE /api/suppliers/:storeId/:supplierId ────────────────────────────────\nrouter.delete(\"/:storeId/:supplierId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, supplierId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const supplier = await prisma.supplier.findFirst({ where: { id: supplierId, storeId } });\n  if (!supplier) throw new AppError(\"Supplier not found\", 404);\n\n  await prisma.supplier.delete({ where: { id: supplierId } });\n  return res.json({ success: true, message: \"Supplier deleted\" });\n});\n\n// ── POST /api/suppliers/:storeId/import/url — scrape product from URL ─────────\nrouter.post(\"/:storeId/import/url\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { url } = z.object({ url: z.string().url() }).parse(req.body);\n\n  const scraped = await supplierService.scrapeProductUrl(url);\n  return res.json({ success: true, data: scraped });\n});\n\n// ── POST /api/suppliers/:storeId/import/save — save scraped product ───────────\nrouter.post(\"/:storeId/import/save\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    supplierId:      z.string().optional(),\n    // Product fields\n    name:            z.string().min(1),\n    description:     z.string().default(\"\"),\n    price:           z.number().positive(),\n    comparePrice:    z.number().optional(),\n    costPrice:       z.number().optional(),   // supplier price\n    images:          z.array(z.string()).default([]),\n    category:        z.string().optional(),\n    inventory:       z.number().int().min(0).default(50),\n    status:          z.enum([\"ACTIVE\",\"DRAFT\"]).default(\"DRAFT\"),\n    // Supplier link fields\n    supplierUrl:     z.string().optional(),\n    supplierSku:     z.string().optional(),\n    supplierPrice:   z.number().optional(),\n    supplierCurrency:z.string().default(\"USD\"),\n    processingDays:  z.number().optional(),\n    shippingDays:    z.number().optional(),\n  }).parse(req.body);\n\n  // Check product plan limits\n  const sub = await prisma.subscription.findFirst({\n    where: { user: { stores: { some: { id: storeId } } } },\n  });\n  const plan = sub?.plan || \"STARTER\";\n  const limits: Record<string, number> = { STARTER: 50, PRO: 500, ADVANCED: 999999 };\n  const count = await prisma.product.count({ where: { storeId } });\n  if (count >= (limits[plan] ?? 50)) {\n    throw new AppError(`Product limit reached for your ${plan} plan`, 403);\n  }\n\n  // Slugify name\n  const base = body.name.toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-|-$/g, \"\");\n  let slug = base;\n  let i = 1;\n  while (await prisma.product.findFirst({ where: { storeId, slug } })) {\n    slug = `${base}-${i++}`;\n  }\n\n  // Create product\n  const product = await (prisma.product as any).create({\n    data: {\n      storeId,\n      slug,\n      name:         body.name,\n      description:  body.description,\n      price:        body.price,\n      comparePrice: body.comparePrice,\n      costPrice:    body.costPrice ?? body.supplierPrice,\n      images:       body.images,\n      category:     body.category,\n      inventory:    body.inventory,\n      status:       body.status,\n    },\n  });\n\n  // Link to supplier if supplierId provided\n  if (body.supplierId && (body.supplierUrl || body.supplierSku)) {\n    await prisma.supplierProduct.upsert({\n      where:  { supplierId_productId: { supplierId: body.supplierId, productId: product.id } },\n      create: {\n        supplierId:       body.supplierId,\n        productId:        product.id,\n        supplierUrl:      body.supplierUrl,\n        supplierSku:      body.supplierSku,\n        supplierPrice:    body.supplierPrice,\n        supplierCurrency: body.supplierCurrency,\n        processingDays:   body.processingDays,\n        shippingDays:     body.shippingDays,\n        lastSynced:       new Date(),\n        stockStatus:      \"IN_STOCK\",\n      },\n      update: {\n        supplierUrl:      body.supplierUrl,\n        supplierSku:      body.supplierSku,\n        supplierPrice:    body.supplierPrice,\n        supplierCurrency: body.supplierCurrency,\n        processingDays:   body.processingDays,\n        shippingDays:     body.shippingDays,\n        lastSynced:       new Date(),\n      },\n    });\n  }\n\n  return res.status(201).json({ success: true, data: product });\n});\n\n// ── GET /api/suppliers/:storeId/products — list supplier-linked products ──────\nrouter.get(\"/:storeId/products/linked\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const linked = await prisma.supplierProduct.findMany({\n    where:   { product: { storeId } },\n    include: {\n      supplier: { select: { id: true, name: true, type: true } },\n      product:  { select: { id: true, name: true, price: true, costPrice: true, status: true, images: true, inventory: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  return res.json({ success: true, data: linked });\n});\n\n// ── PUT /api/suppliers/:storeId/products/:productId/link ──────────────────────\nrouter.put(\"/:storeId/products/:productId/link\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    supplierId:       z.string(),\n    supplierUrl:      z.string().optional(),\n    supplierSku:      z.string().optional(),\n    supplierPrice:    z.number().optional(),\n    supplierCurrency: z.string().default(\"USD\"),\n    processingDays:   z.number().optional(),\n    shippingDays:     z.number().optional(),\n  }).parse(req.body);\n\n  const link = await (prisma.supplierProduct as any).upsert({\n    where:  { supplierId_productId: { supplierId: body.supplierId, productId } },\n    create: { ...body, productId, lastSynced: new Date(), stockStatus: \"IN_STOCK\" },\n    update: { ...body, lastSynced: new Date() },\n  });\n\n  // Also update product costPrice\n  if (body.supplierPrice) {\n    await prisma.product.update({\n      where: { id: productId },\n      data:  { costPrice: body.supplierPrice },\n    });\n  }\n\n  return res.json({ success: true, data: link });\n});\n\n// ── DELETE /api/suppliers/:storeId/products/:productId/link/:supplierId ────────\nrouter.delete(\"/:storeId/products/:productId/link/:supplierId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId, supplierId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  await prisma.supplierProduct.deleteMany({\n    where: { productId, supplierId },\n  });\n\n  return res.json({ success: true, message: \"Supplier link removed\" });\n});\n\n// ── POST /api/suppliers/:storeId/fulfill/:orderId — manual trigger ─────────────\nrouter.post(\"/:storeId/fulfill/:orderId\", async (req: AuthRequest, res: Response) => {\n  const { storeId, orderId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const order = await prisma.order.findFirst({\n    where:   { id: orderId, storeId },\n    include: { items: { include: { product: { include: { supplierProducts: { include: { supplier: true } } } } } } },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { name: true } });\n\n  // Group items by supplier\n  const bySupplier = new Map<string, { supplier: any; items: typeof order.items }>();\n\n  for (const item of order.items) {\n    const link = item.product.supplierProducts?.[0];\n    if (!link?.supplier) continue;\n    const sup = link.supplier;\n    if (!bySupplier.has(sup.id)) bySupplier.set(sup.id, { supplier: sup, items: [] });\n    bySupplier.get(sup.id)!.items.push(item);\n  }\n\n  if (bySupplier.size === 0) {\n    return res.status(400).json({ success: false, message: \"No suppliers linked to items in this order\" });\n  }\n\n  const results: Array<{ supplierId: string; supplierName: string; method: string; success: boolean }> = [];\n\n  for (const [, { supplier, items }] of bySupplier) {\n    const payload: FulfillmentPayload = {\n      orderNumber:     order.orderNumber,\n      orderId:         order.id,\n      customerName:    order.customerName,\n      customerEmail:   order.customerEmail,\n      customerPhone:   order.customerPhone,\n      shippingAddress: order.shippingAddress,\n      storeName:       store?.name ?? storeId,\n      storeId,\n      total:           order.total,\n      currency:        order.currency,\n      notes:           order.notes,\n      items: items.map(i => ({\n        name:        i.name,\n        sku:         i.sku,\n        quantity:    i.quantity,\n        price:       i.price,\n        supplierSku: i.product.supplierProducts?.[0]?.supplierSku ?? null,\n        supplierUrl: i.product.supplierProducts?.[0]?.supplierUrl ?? null,\n      })),\n    };\n\n    let method = \"MANUAL\";\n    let success = false;\n\n    if (supplier.webhookUrl) {\n      method = \"WEBHOOK\";\n      success = await supplierService.fulfillOrderByWebhook(supplier.webhookUrl, payload);\n    } else if (supplier.fulfillEmail) {\n      method = \"EMAIL\";\n      success = await supplierService.fulfillOrderByEmail(supplier.fulfillEmail, supplier.name, payload);\n    } else {\n      method = \"MANUAL\";\n      success = true; // logged as manual\n    }\n\n    // Record fulfillment\n    await (prisma.fulfillmentOrder as any).create({\n      data: {\n        orderId:    order.id,\n        supplierId: supplier.id,\n        storeId,\n        status:     success ? \"SENT\" : \"FAILED\",\n        sentAt:     success ? new Date() : undefined,\n        method,\n        payload:    payload as any,\n      },\n    });\n\n    results.push({ supplierId: supplier.id, supplierName: supplier.name, method, success });\n  }\n\n  return res.json({ success: true, data: results });\n});\n\n// ── GET /api/suppliers/:storeId/fulfillments — list fulfillment records ────────\nrouter.get(\"/:storeId/fulfillments\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const fulfillments = await prisma.fulfillmentOrder.findMany({\n    where:   { storeId },\n    include: { supplier: { select: { id: true, name: true, type: true } } },\n    orderBy: { createdAt: \"desc\" },\n    take:    50,\n  });\n\n  return res.json({ success: true, data: fulfillments });\n});\n\n// ── POST /api/suppliers/:storeId/import/url/batch — scrape multiple URLs ──────\nrouter.post(\"/:storeId/import/url/batch\", async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const { urls } = z.object({\n    urls: z.array(z.string().url()).max(10),\n  }).parse(req.body);\n\n  const results = await Promise.allSettled(\n    urls.map(url => supplierService.scrapeProductUrl(url))\n  );\n\n  const data = results.map((r, i) => ({\n    url:     urls[i],\n    success: r.status === \"fulfilled\",\n    data:    r.status === \"fulfilled\" ? r.value : null,\n    error:   r.status === \"rejected\"  ? r.reason?.message : null,\n  }));\n\n  return res.json({ success: true, data });\n});\n\n// ── GET /api/suppliers/:storeId/products/:productId/suppliers ─────────────────\nrouter.get(\"/:storeId/products/:productId/suppliers\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const assignments = await prisma.supplierProduct.findMany({\n    where: { productId, product: { storeId } },\n    include: { supplier: { select: { id: true, name: true, type: true, isActive: true } } },\n    orderBy: { priority: \"asc\" },\n  });\n\n  return res.json({ success: true, data: assignments });\n});\n\n// ── POST /api/suppliers/:storeId/products/:productId/suppliers ────────────────\nrouter.post(\"/:storeId/products/:productId/suppliers\", async (req: AuthRequest, res: Response) => {\n  const { storeId, productId } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    supplierId:    z.string(),\n    supplierSku:   z.string().optional(),\n    supplierPrice: z.number().optional(),\n    supplierUrl:   z.string().optional(),\n    priority:      z.number().int().min(1).default(1),\n    notes:         z.string().optional(),\n  }).parse(req.body);\n\n  const existing = await prisma.supplierProduct.findFirst({\n    where: { supplierId: body.supplierId, productId },\n  });\n  if (existing) throw new AppError(\"This supplier is already assigned to this product\", 409);\n\n  const assignment = await (prisma.supplierProduct as any).create({\n    data: { ...body, productId },\n    include: { supplier: { select: { id: true, name: true, type: true } } },\n  });\n\n  return res.status(201).json({ success: true, data: assignment });\n});\n\n// ── PATCH /api/suppliers/:storeId/supplier-products/:id ───────────────────────\nrouter.patch(\"/:storeId/supplier-products/:id\", async (req: AuthRequest, res: Response) => {\n  const { storeId, id } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n\n  const body = z.object({\n    priority:      z.number().int().min(1).optional(),\n    isActive:      z.boolean().optional(),\n    supplierSku:   z.string().optional(),\n    supplierPrice: z.number().optional(),\n    notes:         z.string().optional(),\n    stockStatus:   z.string().optional(),\n  }).parse(req.body);\n\n  const updated = await prisma.supplierProduct.update({ where: { id }, data: body });\n  return res.json({ success: true, data: updated });\n});\n\n// ── DELETE /api/suppliers/:storeId/supplier-products/:id ─────────────────────\nrouter.delete(\"/:storeId/supplier-products/:id\", async (req: AuthRequest, res: Response) => {\n  const { storeId, id } = req.params;\n  await requireStoreOwner(storeId, req.user!.userId, req.user!.role);\n  await prisma.supplierProduct.delete({ where: { id } });\n  return res.json({ success: true });\n});\n\n\nexport default router;\n"};
